sp_widget.css:
.imgIndicador {
  font-family: 'Roboto Flex', sans-serif !important;
  position: relative;
  padding: 0 2rem; /* espaço lateral */
  box-sizing: border-box;
  display: flex;
  justify-content: center;
  height: 500px;
}

.imgIndicador img {
  width: 100%;
  height: 100%;
  max-width: 100%;
  object-fit: cover;
  display: block;
  position: relative; /* para overlay se posicionar relativo a essa imagem */
  z-index: 0;
}

.overlay {
  position: absolute;
  top: 0;
  left: 2rem;    /* começa após o padding esquerdo */
  right: 2rem;   /* termina antes do padding direito */
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  z-index: 1;
}

.textoSobreImagem {
  font-family: 'Roboto Flex', sans-serif !important;
  position: absolute;
  top: 17rem;
  left: 9rem; /* alinhado com o padding */
  color: white;
  z-index: 2;
  max-width: calc(100% - 4rem); /* para respeitar os 2rem de cada lado */
}

  @media (max-width: 600px) {
    .textoSobreImagem {
    	    transform: translateX(-47px) translateY(101px);
      		font-size: 13px;
    }
        }
